    w = int(g.get("grid_width", 0) or 0)
    h = int(g.get("grid_height", 0) or 0)

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return (int(v[0]), int(v[1]))
        if isinstance(v, dict):
            if "position" in v: return pos(v["position"])
            if "pos" in v: return pos(v["pos"])
            if "x" in v and "y" in v: return (int(v["x"]), int(v["y"]))
        return None

    def collect(x):
        if x is None: return []
        if isinstance(x, (list, tuple)):
            r = []
            for i in x: r += collect(i)
            return r
        p = pos(x)
        return [p] if p is not None else []

    s = pos(g.get("self_position"))
    o = pos(g.get("opponent_position"))
    res = collect(g.get("resources"))
    obs = set(collect(g.get("obstacles")))
    if s is None: return [0, 0]

    moves = [(0,0),(1,0),(-1,0),(0,1),(0,-1)]
    best = (0, 0)
    bestv = None
    for dx, dy in moves:
        nx, ny = s[0] + dx, s[1] + dy
        if w and (nx < 0 or nx >= w): continue
        if h and (ny < 0 or ny >= h): continue
