        score = 0
        if res:
            d = min(abs(nx - rx) + abs(ny - ry) for rx, ry in res)
            score -= d * 10
            if (nx, ny) in res: score += 1000
        if o is not None:
            od = abs(nx - o[0]) + abs(ny - o[1])
            score += od
        if (nx, ny) in obs: score -= 1000
        if bestv is None or score > bestv:
            bestv = score
            best = (dx, dy)

    if res:
        tx, ty = min(res, key=lambda p: abs(p[0]-s[0]) + abs(p[1]-s[1]))
        dx = 0 if tx == s[0] else (1 if tx > s[0] else -1)
        dy = 0 if ty == s[1] else (1 if ty > s[1] else -1)
        if (s[0] + dx, s[1] + dy) not in obs:
            if (not w or 0 <= s[0] + dx < w) and (not h or 0 <= s[1] + dy < h):
                return [dx, dy]
    return [best[0], best[1]]

